const colours = [
  { name: "Chart 1", token: "--ayy-chart-1" },
  { name: "Chart 2", token: "--ayy-chart-2" },
  { name: "Chart 3", token: "--ayy-chart-3" },
  { name: "Chart 4", token: "--ayy-chart-4" },
  { name: "Chart 5", token: "--ayy-chart-5" },
  { name: "Chart 6", token: "--ayy-chart-6" },
